<?php
session_start();
require 'db.php';
require_once 'schema_helpers.php';
require_once 'activity_log_helper.php';
if (!isset($_SESSION['user_id']) || ($_SESSION['role'] ?? '') !== 'Cashier') { header('Location: login.php'); exit(); }
ensureRepairAutomationSchema($conn);
$repairId = (int)($_GET['repair_id'] ?? $_POST['repair_id'] ?? 0);
$repairStmt = $conn->prepare('SELECT r.repair_id, r.booking_id, r.ebike_model, r.customer_id, u.name customer_name, tr.report_id, tr.work_performed, tr.technician_notes FROM repairs r LEFT JOIN users u ON u.user_id=r.customer_id LEFT JOIN technician_repair_reports tr ON tr.repair_id=r.repair_id WHERE r.repair_id=?');
$repairStmt->bind_param('i', $repairId); $repairStmt->execute(); $repair = $repairStmt->get_result()->fetch_assoc();
if (!$repair) { http_response_code(404); exit('Repair record not found.'); }
$reportId = (int)($repair['report_id'] ?? 0);
if ($_SERVER['REQUEST_METHOD'] === 'POST' && $reportId > 0) {
  $conn->query('DELETE FROM repair_charge_items WHERE report_id=' . $reportId);
  $types=$_POST['item_type']??[]; $names=$_POST['item_name']??[]; $qtys=$_POST['quantity']??[]; $prices=$_POST['unit_price']??[]; $total=0.0;
  $item=$conn->prepare('INSERT INTO repair_charge_items (report_id,item_type,item_name,quantity,unit_price) VALUES (?,?,?,?,?)');
  foreach($names as $i=>$name){ $name=trim((string)$name); if($name==='') continue; $type=in_array($types[$i]??'', ['Labor','Part','Other'],true)?$types[$i]:'Other'; $qty=max(.01,(float)($qtys[$i]??1)); $price=max(0,(float)($prices[$i]??0)); $item->bind_param('issdd',$reportId,$type,$name,$qty,$price); $item->execute(); $total+=$qty*$price; }
  $update=$conn->prepare('UPDATE repairs SET amount=? WHERE repair_id=?'); $update->bind_param('di',$total,$repairId); $update->execute();
  $booking=$conn->prepare('UPDATE repair_bookings SET estimated_amount=? WHERE booking_id=?'); $booking->bind_param('di',$total,$repair['booking_id']); $booking->execute();
  syncBookingPaymentToPayments($conn, (int)$repair['booking_id'], 'Cashier');
  logActivity($conn,(int)$_SESSION['user_id'],'Cashier','Payment summary saved','Prepared itemized payment summary for repair #'.$repairId.'.','repair',$repairId);
  header('Location: cashierpaymentbreakdown.php?repair_id='.$repairId.'&saved=1'); exit();
}
$items=[]; if($reportId){$result=$conn->query('SELECT * FROM repair_charge_items WHERE report_id='.$reportId.' ORDER BY item_id'); while($row=$result->fetch_assoc())$items[]=$row;} if(!$items)$items[]=['item_type'=>'Labor','item_name'=>'','quantity'=>1,'unit_price'=>0];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Summary - FixTrack</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.5/font/bootstrap-icons.css" rel="stylesheet"><style>.cashier-summary{margin:28px 32px 48px}.summary-total{font-size:1.15rem;font-weight:800}</style></head><body><?php include 'navbarcashier.php'; ?><main class="cashier-summary"><div class="page-hero"><h1 class="h3 mb-1">Customer Payment Summary</h1><p>Repair #<?= $repairId ?> · <?= htmlspecialchars($repair['customer_name'] ?? 'Customer') ?> · <?= htmlspecialchars($repair['ebike_model']) ?></p></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Payment summary saved and ready for the customer.</div><?php endif;?><?php if(!$reportId):?><div class="alert alert-warning">The technician must submit a service report before the cashier can prepare the payment summary.</div><a class="btn btn-outline-secondary" href="cashiertransactions.php">Back to payments</a><?php else:?><div class="card shadow-sm"><div class="card-body p-4"><div class="mb-4"><strong>Technician work report</strong><p class="mb-0 text-muted"><?= nl2br(htmlspecialchars($repair['work_performed'] ?: $repair['technician_notes'] ?: 'No work notes recorded.')) ?></p></div><form method="post"><input type="hidden" name="repair_id" value="<?= $repairId ?>"><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h5 mb-0">Charges to pay</h2><button class="btn btn-outline-success btn-sm" type="button" id="addItem"><i class="bi bi-plus-lg me-1"></i>Add charge</button></div><div class="table-responsive"><table class="table align-middle" id="itemsTable"><thead class="table-light"><tr><th>Type</th><th>Part or service</th><th>Qty</th><th>Unit price</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><select class="form-select" name="item_type[]"><option <?= $item['item_type']==='Labor'?'selected':'' ?>>Labor</option><option <?= $item['item_type']==='Part'?'selected':'' ?>>Part</option><option <?= $item['item_type']==='Other'?'selected':'' ?>>Other</option></select></td><td><input class="form-control" name="item_name[]" value="<?= htmlspecialchars($item['item_name']) ?>" required></td><td><input class="form-control line-qty" type="number" min=".01" step=".01" name="quantity[]" value="<?= htmlspecialchars((string)$item['quantity']) ?>"></td><td><input class="form-control line-price" type="number" min="0" step=".01" name="unit_price[]" value="<?= htmlspecialchars((string)$item['unit_price']) ?>"></td><td class="line-total">PHP 0.00</td><td><button class="btn btn-outline-danger btn-sm remove-item" type="button" aria-label="Remove charge"><i class="bi bi-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex justify-content-end border-top pt-3"><span class="summary-total">Total payable: <span id="grandTotal">PHP 0.00</span></span></div><button class="btn btn-success mt-4" type="submit"><i class="bi bi-floppy me-1"></i>Save payment summary</button><a class="btn btn-outline-secondary mt-4 ms-2" href="cashiertransactions.php">Back</a></form></div></div><?php endif;?></main><template id="itemTemplate"><tr><td><select class="form-select" name="item_type[]"><option>Labor</option><option selected>Part</option><option>Other</option></select></td><td><input class="form-control" name="item_name[]" required></td><td><input class="form-control line-qty" type="number" min=".01" step=".01" name="quantity[]" value="1"></td><td><input class="form-control line-price" type="number" min="0" step=".01" name="unit_price[]" value="0"></td><td class="line-total">PHP 0.00</td><td><button class="btn btn-outline-danger btn-sm remove-item" type="button" aria-label="Remove charge"><i class="bi bi-trash"></i></button></td></tr></template><script>const b=document.querySelector('#itemsTable tbody');function t(){let s=0;b.querySelectorAll('tr').forEach(r=>{let x=(+r.querySelector('.line-qty').value||0)*(+r.querySelector('.line-price').value||0);r.querySelector('.line-total').textContent='PHP '+x.toFixed(2);s+=x});document.querySelector('#grandTotal').textContent='PHP '+s.toFixed(2)}if(b){document.querySelector('#addItem').onclick=()=>{b.insertAdjacentHTML('beforeend',document.querySelector('#itemTemplate').innerHTML);t()};b.oninput=t;b.onclick=e=>{if(e.target.closest('.remove-item')&&b.rows.length>1){e.target.closest('tr').remove();t()}};t()}</script></body></html>
